generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

model User {
  id Int @id @default(autoincrement())
  email String @unique
  name String?
  posts Post[]
}

model Post {
  id Int @id @default(autoincrement())
  title String
  published Boolean @default(false)
  createdAt DateTime @default(now())
  authorId Int
  author User @relation(fields: [authorId], references: [id])
}

