const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  const users = await prisma.user.findMany({ include: { posts: true } });
  console.log('Users:', JSON.stringify(users, null, 2));

  try {
    const migrations = await prisma.$queryRawUnsafe('SELECT * FROM _prisma_migrations;');
    console.log('Migrations in DB:', migrations);
  } catch (err) {
    console.error('Error querying migrations:', err);
  }
}

main()
  .catch(e => console.error(e))
  .finally(async () => {
    await prisma.$disconnect();
  });

const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  const result = await prisma.$executeRawUnsafe(`DELETE FROM _prisma_migrations WHERE migration_name != '0001_baseline';`);
  console.log('Deleted old migrations:', result);
}

main()
  .catch(e => console.error(e))
  .finally(async () => {
    await prisma.$disconnect();
  });
